document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll("input, select, textarea").forEach(function(e){e.addEventListener("input",function(){e.classList.remove("border-red-600","focus:ring-red-600","focus:border-red-600","focus:text-red-600","dark:border-red-600","dark:focus:ring-red-600","dark:focus:border-red-600","dark:focus:text-red-600");const r=document.getElementById(e.id+"_error");r&&r.remove()})})});
